"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[49],{9335(e){e.exports=JSON.parse('{"tag":{"label":"complexity","permalink":"/azeon/p-vs-np/tags/complexity","allTagsPath":"/azeon/p-vs-np/tags","count":8,"items":[{"id":"np-completeness/14-3-sat-the-building-block","title":"3-SAT: The Building Block","description":"Why restricting every clause to exactly three literals keeps SAT just as hard, and how the reduction from SAT to 3-SAT actually works step by step.","permalink":"/azeon/p-vs-np/np-completeness/3-sat-the-building-block"},{"id":"foundations/exponential-explosions","title":"Exponential Explosions","description":"Why O(2^n) isn\'t just slow. It\'s practically impossible. And what a chessboard grain of wheat teaches us about the limits of computation.","permalink":"/azeon/p-vs-np/foundations/exponential-explosions"},{"id":"np-completeness/polynomial-time-reductions","title":"Reductions","description":"If you can solve one problem, can you solve another? Reductions are the tool that lets us answer that question precisely, and they are the key to everything in Phase 2.","permalink":"/azeon/p-vs-np/np-completeness/polynomial-time-reductions"},{"id":"foundations/solving-vs-verifying","title":"Solving vs. Verifying","description":"The gap between finding an answer and checking one feels obvious the moment you see it. This post asks why that obvious gap is also the deepest open question in all of computer science.","permalink":"/azeon/p-vs-np/foundations/solving-vs-verifying"},{"id":"np-completeness/the-clique-problem","title":"The Clique Problem","description":"What does finding mutual friends in a social network have to do with Boolean logic? The reduction from 3-SAT to Clique is the bridge, and it is one of the most satisfying constructions in all of NP-Completeness.","permalink":"/azeon/p-vs-np/np-completeness/the-clique-problem"},{"id":"np-completeness/the-cook-levin-theorem","title":"The Cook-Levin Theorem","description":"In 1971, Stephen Cook proved that one specific problem sits at the top of the entire NP hierarchy, and that solving it would solve everything else. This is the result that launched the field of NP-Completeness.","permalink":"/azeon/p-vs-np/np-completeness/the-cook-levin-theorem"},{"id":"np-completeness/the-sat-problem","title":"The SAT Problem","description":"Boolean Satisfiability built from scratch: logic gates, what CNF actually means, and why this one problem became the thing everything else in NP reduces to.","permalink":"/azeon/p-vs-np/np-completeness/the-sat-problem"},{"id":"np-completeness/vertex-cover","title":"The Vertex Cover Problem","description":"Back in Post 11 I used cameras on roads to explain what a reduction is. I never proved that problem was NP-Complete. Today I finally do, and it takes almost no new work.","permalink":"/azeon/p-vs-np/np-completeness/vertex-cover"}],"unlisted":false}}')}}]);